            .add_step("y", vec!["x".to_string()])
            .build()
            .unwrap();

        let groups = graph.parallel_groups().unwrap();
        // Group 1: [a, x], Group 2: [b, y]
        assert_eq!(groups.len(), 2);
        assert!(groups[0].contains(&"a".to_string()));
        assert!(groups[0].contains(&"x".to_string()));
        assert!(groups[1].contains(&"b".to_string()));
        assert!(groups[1].contains(&"y".to_string()));
    }
}

